const xored = Array.from(l1).map((c) => c.charCodeAt(0) ^ 0x5a);
const l3 = xored.map((b) => b.toString(16).padStart(2, "0")).join("");
const l4 = Buffer.from(l3, "utf8").toString("base64");
const l5 = l4.split("").reverse().join("");
console.log(l5);
module.exports = { plain, l5 };
